}

pieces = {
 'A3h': [(1,2),(1,3)], 'B6v': [(1,7),(2,7)], 'C7v': [(2,5),(3,5)],
 'D8h': [(3,1),(3,2)], 'E6h': [(4,8),(4,9)], 'F3h': [(5,4),(5,5)],
 'G9v': [(6,2),(7,2)], 'H4v': [(6,8),(7,8)], 'I1h': [(8,5),(8,6)],
 'J5h': [(9,7),(9,8)], 'K3v': [(8,0),(9,0)]}
# top barrier row 0; process objects by original uppermost row, repeatedly translate upward to stable against fixed barrier/placed objects
occ = {(0,c):2 for c in range(10)}
placed = {}
for name, cells in sorted(pieces.items(), key=lambda kv:min(r for r,c in kv[1])):
    cells = list(cells)
    while True:
        shifted = [(r-1,c) for r,c in cells]
        if any(r <= 0 or (r,c) in occ for r,c in shifted): break
        cells = shifted
    placed[name] = cells
    for cell in cells: occ[cell] = int(name[1])
grid = [[0]*10 for _ in range(10)]
for (r,c),v in occ.items(): grid[r][c]=v
print(placed)
for row in grid: print(row)

